input.command:
cd D:\pal
$checks = @()
$tally = 'backend/app/integrations/tally/client.py','backend/app/integrations/tally/xml.py','backend/app/integrations/tally/parser.py','backend/app/integrations/tally/service.py','backend/app/integrations/tally/exceptions.py','backend/app/api/v1/tally/router.py','backend/app/services/tally_sync.py','backend/app/services/tally_mapping_sync.py','backend/app/services/voucher_posting.py','backend/app/models/tally_sync.py','backend/app/schemas/tally.py','src/lib/api/tally.ts','src/lib/queries/tally.ts','src/routes/tally.tsx','docs/tallyprime-poc.md'
$checks += [pscustomobject]@{name='fifteen_tally_integration_surfaces_present'; actual=@($tally | Where-Object { Test-Path $_ }).Count; expected=15}
$areas = 'backend/app/main.py','backend/app/api/v1/router.py','backend/alembic/versions','backend/app/services/invoice_extraction.py','backend/app/services/bank_extraction.py','backend/app/services/ledger_suggestion.py','backend/app/services/voucher.py','backend/app/integrations/tally/service.py','src/routes/review.tsx','backend/tests/conftest.py'
$checks += [pscustomobject]@{name='ten_focus_area_surfaces_present'; actual=@($areas | Where-Object { Test-Path $_ }).Count; expected=10}
$checks += [pscustomobject]@{name='head_unchanged_no_commit_and_no_push'; actual=[string](git rev-parse --short HEAD); expected='b2d3a58'}
$before = (git status --porcelain | Out-String)
$beforeCount = @($before -split "`r?`n" | Where-Object { $_ -ne '' }).Count
Start-Sleep -Seconds 25
$after = (git status --porcelain | Out-String)
$delta = 0
if ($before -ne $after) { $delta = 1 }
$checks += [pscustomobject]@{name='churn_snapshot_identical_over_remeasurement_window'; actual=$delta; expected=0}
$afterCount = @($after -split "`r?`n" | Where-Object { $_ -ne '' }).Count
$checks += [pscustomobject]@{name='working_tree_churn_entry_count_stable'; actual=$afterCount; expected=$beforeCount}
$checks += [pscustomobject]@{name='session_started_servers_no_longer_running'; actual=@(Get-Process -Id 33408,37868,9308 -ErrorAction SilentlyContinue).Count; expected=0}
$installs = 0
if (Test-Path 'C:\Program Files\PostgreSQL') { $installs++ }
if (Test-Path 'D:\pal\.pgdata') { $installs++ }
$checks += [pscustomobject]@{name='no_postgres_install_or_local_pgdata_created_by_session'; actual=$installs; expected=0}
$dbline = (Get-Content backend\.env | Select-String -Pattern '^DATABASE_URL=').Line
$envOk = 0
if ($dbline -match '@localhost:5432/pal_db$') { $envOk = 1 }
$checks += [pscustomobject]@{name='backend_env_database_url_left_unchanged'; actual=$envOk; expected=1}
Write-Output "detail beforeCount=$beforeCount afterCount=$afterCount delta=$delta"
$payload = [pscustomobject]@{version=1; checks=$checks}
Write-Output ('{"harnessVerification":' + (ConvertTo-Json -Compress -Depth 4 $payload) + '}')
